import time

def retry(max_attempts=3, delay=0):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print('[시도 ' + str(attempt) + '/' + str(max_attempts) + '] 실패: ' + str(e))
