class Orchestrator:
    def __init__(self, agents):
        self.agents = agents
    def dispatch(self, task):
        print('[작업] ' + task)
        for agent in self.agents:
            if agent.can_handle(task):
                result = agent.run(task)
                print('  → ' + result)
                return result
        print('  → 처리 가능한 에이전트 없음')
        return None

